    var ADDS = [{"p":"PART 3. 신라","q":[{"answer":"O","text":"화려한 금관이 출토된 금관총과 황남대총은 경주에 도읍한 신라의 무덤으로, 금관은 신라 금속 공예의 뛰어난 수준을 보여 준다.","exp":"금관총 금관·황남대총 금관 등 화려한 금관은 경주에 도읍한 신라를 대표하는 문화유산이다. 신라의 돌무지덧널무덤은 도굴이 어려워 이런 금관과 껴묻거리가 온전히 보존될 수 있었다는 점을 함께 기억한다.","src":"한능검 제75회"},{"answer":"X","text":"화려한 금관이 출토된 금관총과 황남대총은 경주에 도읍한 신라의 무덤으로, 이 금관들은 가야 연맹의 대표적인 금속 공예품으로 평가된다.","exp":"금관의 소속이 틀렸다. 금관총·황남대총의 화려한 금관은 가야가 아니라 경주에 도읍한 신라의 문화유산이다. 가야는 덩이쇠 등 철기 공예로 유명할 뿐 이런 금관을 대표 유물로 남기지 않았다."}],"tb":[{"k":"p","t":"경주에 도읍한 신라의 대표적 문화유산으로 금관총 금관·황남대총 금관 등 화려한 금관이 있다. 신라의 돌무지덧널무덤은 도굴이 어려워 금관을 비롯한 껴묻거리가 온전히 보존되었다."}],"wi":[]},{"p":"PART 1. 고구려","q":[{"answer":"O","text":"고구려 영류왕 때 부여성에서 바다에 이르는 천리장성을 쌓기 시작하였고, 이후 연개소문이 정변을 일으켜 권력을 장악하였다.","exp":"당의 침입에 대비해 영류왕 때 천리장성 축조가 시작되었고, 그 공사를 감독하던 연개소문이 642년 정변을 일으켜 영류왕을 제거하고 대막리지가 되어 권력을 장악하였다. 천리장성 착공이 먼저이고 연개소문 정변이 그 뒤라는 순서를 함께 기억한다.","src":"한능검 제75회"},{"answer":"X","text":"고구려에서는 을지문덕이 살수에서 수의 대군을 물리친 612년에 곧바로 연개소문이 정변을 일으켜 권력을 장악하고 천리장성을 쌓기 시작하였다.","exp":"시점이 틀렸다. 연개소문의 정변은 살수 대첩(612) 직후가 아니라 영류왕 때 천리장성 축조가 시작된 이후인 642년의 일이다. 살수 대첩과 연개소문 정변 사이에는 30년의 간격이 있으므로 두 사건을 붙여 서술하면 오답이다."}],"tb":[{"k":"p","t":"고구려는 당의 침입에 대비해 영류왕 때 부여성에서 바다에 이르는 천리장성을 쌓기 시작하였다. 그 공사를 감독하던 연개소문이 642년 정변을 일으켜 영류왕을 제거하고 대막리지가 되어 권력을 장악하였다."}],"wi":[]}];
