    var ADDS = [{"p":"PART 1. 고구려","q":[{"answer":"O","text":"연개소문이 정변을 일으켜 영류왕을 죽이고 권력을 장악하였다.","exp":"642년 연개소문은 정변으로 영류왕을 제거하고 대막리지가 되어 실권을 잡았으며, 이는 살수대첩(612)과 안시성 싸움(645) 사이의 사건이다. 이 정변이 당 태종의 침입을 부른 배경이 되었다.","src":"한능검 제69회"},{"answer":"X","text":"연개소문이 정변을 일으켜 영류왕을 죽이고 권력을 잡은 뒤 스스로 왕위에 올랐다.","exp":"앞은 옳으나 마지막이 틀렸다. 연개소문은 정변 뒤 왕위에 오른 것이 아니라 최고 관직인 대막리지가 되어 실권을 장악하였고, 왕위에는 보장왕을 세웠다."}],"tb":[],"wi":["📝 \"연개소문이 정변을 일으켜 왕위에 올랐다\" → ❌ 대막리지가 되어 실권을 잡았을 뿐 왕위에는 보장왕을 세움"]},{"p":"PART 1. 고구려","q":[{"answer":"O","text":"고구려가 멸망한 뒤 검모잠이 보장왕의 외손 안승을 왕으로 받들어 고구려 부흥 운동을 전개하였다.","exp":"고구려 멸망(668) 뒤 검모잠은 안승을 왕으로 추대해 부흥 운동을 일으켰다. 복신·도침·흑치상지가 이끈 백제 부흥 운동과 나라를 구분해 기억한다.","src":"한능검 제69회"},{"answer":"X","text":"고구려가 멸망한 뒤 검모잠이 의자왕의 아들 부여풍을 왕으로 받들어 고구려 부흥 운동을 전개하였다.","exp":"검모잠이 받든 인물이 틀렸다. 검모잠은 보장왕의 외손 안승을 왕으로 세웠고, 부여풍은 복신 등이 옹립한 백제 부흥 운동의 왕이다."}],"tb":[{"k":"p","t":"고구려 멸망(668) 뒤 검모잠이 보장왕의 외손 안승을 왕으로 받들어 부흥 운동을 일으켰다. 백제에서는 복신·도침·흑치상지가 주류성·임존성을 근거로 부흥 운동을 전개하였다."}],"wi":[]},{"p":"PART 1. 고구려","q":[{"answer":"O","text":"충주 고구려비는 남한 지역에서 유일하게 발견된 고구려비로, 고구려의 남한강 유역 진출을 보여 준다.","exp":"충주(중원) 고구려비는 남한에서 발견된 유일한 고구려비로, 장수왕 대 남진 정책의 결과를 전한다. 만주 지안의 광개토대왕릉비와 위치를 구분한다.","src":"한능검 제69회"},{"answer":"X","text":"충주 고구려비는 남한 지역에서 유일하게 발견된 고구려비로, 백제의 한강 유역 진출을 보여 준다.","exp":"앞은 옳으나 마지막이 틀렸다. 충주 고구려비는 백제가 아니라 고구려의 남한강 유역 진출을 보여 주는 금석문으로, 장수왕의 남진을 전한다."}],"tb":[],"wi":["충주 고구려비 = 남한에서 유일하게 발견된 고구려비 (북한·만주에서 발견되었다고 하면 ❌)"]},{"p":"PART 2. 백제","q":[{"answer":"O","text":"무령왕은 중국 남조의 양나라에 사신을 보내 외교 관계를 강화하였다.","exp":"무령왕은 남조 양과 교류하며 국제적 지위를 높였고, 무령왕릉의 벽돌무덤 양식도 이 교류를 보여 준다. 22담로 왕족 파견과 함께 웅진기 중흥의 왕으로 묶는다.","src":"한능검 제69회"},{"answer":"X","text":"무령왕은 중국 북조의 북위에 사신을 보내 외교 관계를 강화하였다.","exp":"교류한 상대가 틀렸다. 무령왕이 사신을 보내 관계를 강화한 나라는 북조의 북위가 아니라 남조의 양이다. 무령왕릉의 벽돌무덤도 남조와의 교류를 보여 준다."}],"tb":[],"wi":[]},{"p":"PART 2. 백제","q":[{"answer":"O","text":"백제가 멸망한 뒤 복신과 도침, 흑치상지 등이 주류성과 임존성을 근거로 백제 부흥 운동을 일으켰다.","exp":"백제 멸망(660) 뒤 복신·도침·흑치상지가 주류성·임존성에서 부흥 운동을 전개하였다. 검모잠·안승이 이끈 고구려 부흥 운동과 나라를 구분한다.","src":"한능검 제69회"},{"answer":"X","text":"백제가 멸망한 뒤 검모잠과 안승 등이 주류성과 임존성을 근거로 백제 부흥 운동을 일으켰다.","exp":"부흥 운동을 이끈 인물이 틀렸다. 검모잠과 안승은 백제가 아니라 고구려 부흥 운동의 주역이며, 백제 부흥은 복신·도침·흑치상지가 주도하였다."}],"tb":[{"k":"p","t":"백제 멸망(660) 뒤 복신·도침·흑치상지가 주류성·임존성을 근거로 부흥 운동을 일으키고 왜에 있던 부여풍(풍왕)을 왕으로 맞았으나 실패하였다."}],"wi":[]},{"p":"PART 3. 신라","q":[{"answer":"O","text":"진흥왕은 대아찬 거칠부에게 명하여 역사서인 국사를 편찬하게 하였다.","exp":"진흥왕은 거칠부에게 국사를 편찬하게 하여 왕실의 권위를 높였다. 백제 근초고왕의 서기(고흥), 고구려의 신집(이문진)과 함께 삼국의 역사서로 묶어 구분한다.","src":"한능검 제69회"},{"answer":"X","text":"법흥왕은 대아찬 거칠부에게 명하여 역사서인 국사를 편찬하게 하였다.","exp":"주체가 틀렸다. 거칠부에게 국사를 편찬하게 한 것은 법흥왕이 아니라 진흥왕이다. 법흥왕은 율령 반포·병부 설치·불교 공인·금관가야 병합을 이룬 왕이다."}],"tb":[{"k":"p","t":"진흥왕은 대아찬 거칠부에게 명하여 역사서 국사를 편찬하게 하였다. 백제 근초고왕의 서기(고흥), 고구려 영양왕의 신집(이문진)과 함께 삼국의 대표 역사서로 묶는다."}],"wi":[]},{"p":"PART 3. 신라","q":[{"answer":"O","text":"북한산 진흥왕 순수비는 조선 후기 김정희가 금석과안록에서 그 정체를 밝혀낸 신라의 순수비이다.","exp":"북한산비는 무학대사비 등으로 잘못 알려졌다가 김정희가 금석과안록에서 진흥왕 순수비임을 고증하였다. 진흥왕의 한강 유역 진출을 보여 주는 금석문이다.","src":"한능검 제69회"},{"answer":"X","text":"북한산 진흥왕 순수비는 조선 후기 정약용이 금석과안록에서 그 정체를 밝혀낸 신라의 순수비이다.","exp":"고증한 인물이 틀렸다. 북한산 순수비가 진흥왕비임을 금석과안록에서 밝힌 사람은 정약용이 아니라 김정희이다. 이전에는 무학대사비 등으로 잘못 알려져 있었다."}],"tb":[{"k":"p","t":"진흥왕은 한강 유역과 대가야 등을 정복하고 북한산·창녕·황초령·마운령에 순수비를 세웠다. 북한산비는 조선 후기 김정희가 금석과안록에서 진흥왕 순수비임을 고증하였다."}],"wi":[]},{"p":"PART 3. 신라","q":[{"answer":"O","text":"사찬 시득이 기벌포에서 설인귀가 이끄는 당의 군대를 격파하였다.","exp":"676년 신라는 기벌포 싸움에서 설인귀의 당군을 물리쳐 나당 전쟁을 승리로 마무리하고 삼국 통일을 완성하였다. 매소성 전투와 함께 대당 항쟁의 대표적 승리이다.","src":"한능검 제69회"},{"answer":"X","text":"사찬 시득이 살수에서 설인귀가 이끄는 당의 군대를 격파하였다.","exp":"전투 장소가 틀렸다. 시득이 당의 설인귀 군을 격파한 곳은 살수가 아니라 기벌포이다. 살수는 을지문덕이 수의 군대를 무찌른 살수대첩의 무대이다."}],"tb":[{"k":"p","t":"나당 전쟁에서 신라는 매소성 전투와 기벌포 싸움(676, 사찬 시득이 설인귀의 당군 격파)으로 당을 몰아내고 삼국 통일을 완성하였다."}],"wi":[]},{"p":"PART 5. 삼국 문화·대외 교류·종합","q":[{"answer":"O","text":"연가 7년명 금동여래입상은 광배 뒷면에 새겨진 연가라는 연호를 통해 고구려에서 만들어진 불상임을 알 수 있다.","exp":"경남 의령에서 출토된 연가 7년명 금동여래입상은 광배 뒷면 명문의 연가 연호로 고구려 불상임이 확인된다. 신라 계통의 다른 불상과 제작국을 구분한다.","src":"한능검 제69회"},{"answer":"X","text":"연가 7년명 금동여래입상은 광배 뒷면에 새겨진 연가라는 연호를 통해 백제에서 만들어진 불상임을 알 수 있다.","exp":"제작한 나라가 틀렸다. 연가 7년명 금동여래입상은 백제가 아니라 고구려에서 만든 불상으로, 광배 뒷면의 연가 연호가 이를 뒷받침한다."}],"tb":[{"k":"p","t":"연가 7년명 금동여래입상은 광배 뒷면의 '연가 7년' 연호를 통해 고구려에서 제작된 것으로 확인되는 대표적 삼국 시대 불상으로, 경남 의령에서 출토되었다."}],"wi":["연가 7년명 금동여래입상 = 고구려 불상 (연가 연호가 근거, 백제·신라 제작이라 하면 ❌)"]}];
    for (var ai = 0; ai < ADDS.length; ai++) { insQ(ADDS[ai].p, ADDS[ai].q); insT(ADDS[ai].p, ADDS[ai].tb, ADDS[ai].wi); }
    var TAGS = [{"n":"22담로에 왕족을 파견하여 지방에 대한 중앙의 통제력을 강화","l":"한능검 제69회"}];
    for (var ti2 = 0; ti2 < TAGS.length; ti2++) tagSrc(TAGS[ti2].n, TAGS[ti2].l);
